js:
var input=root.querySelector('.ti2-filled-counter-input');
var num=root.querySelector('.ti2-filled-counter-num');
var ring=root.querySelector('.ti2-filled-counter-rfg');
var msg=root.querySelector('.ti2-filled-counter-msg');
var shell=root.querySelector('.ti2-filled-counter-shell');
var LIMIT=60,last=-1,wasOver=false;
function paint(){
  var n=input.value.length;
  var pct=Math.min(n/LIMIT,1);
  ring.style.strokeDashoffset=(100-pct*100).toFixed(2);
  if(n!==last){
    num.textContent=String(n);
    num.classList.remove('ti2-filled-counter-tick');
    void num.offsetWidth;
    num.classList.add('ti2-filled-counter-tick');
    last=n;
  }
  var over=n>LIMIT,near=!over&&n>LIMIT-10;
  root.classList.toggle('ti2-filled-counter-over',over);
  root.classList.toggle('ti2-filled-counter-near',near);
  input.setAttribute('aria-invalid',over?'true':'false');
  msg.textContent=over?(n-LIMIT)+' characters over':n===0?'Headline is required':near?'Nearly at the limit':'Looks good';
  if(over&&!wasOver){
    shell.classList.remove('ti2-filled-counter-shake');
    void shell.offsetWidth;
    shell.classList.add('ti2-filled-counter-shake');
  }
  wasOver=over;
}
input.addEventListener('input',paint);
paint();

