js:
var ta=root.querySelector('.ti2-autogrow-note-input');
var mirror=root.querySelector('.ti2-autogrow-note-mirror');
var lines=root.querySelector('.ti2-autogrow-note-lines');
var send=root.querySelector('.ti2-autogrow-note-send');
var txt=root.querySelector('.ti2-autogrow-note-txt');
var MIN=30,MAX=88,LH=20,PAD=8,timer=0;
function measure(){
  mirror.textContent=ta.value+' ';
  var h=Math.ceil(mirror.scrollHeight);
  ta.style.height=Math.max(MIN,Math.min(MAX,h))+'px';
  ta.style.overflowY=h>MAX?'auto':'hidden';
  var rows=Math.max(1,Math.round((h-PAD)/LH));
  var has=ta.value.trim().length>0;
  lines.textContent=has?(rows===1?'1 line':rows+' lines'):'Empty';
  send.disabled=!has;
  root.classList.toggle('ti2-autogrow-note-ready',has);
}
function post(){
  if(send.disabled)return;
  send.disabled=true;
  txt.textContent='Posted';
  root.classList.add('ti2-autogrow-note-sent');
  clearTimeout(timer);
  timer=setTimeout(function(){
    ta.value='';
    txt.textContent='Post';
    root.classList.remove('ti2-autogrow-note-sent');
    measure();
  },1000);
}
ta.addEventListener('input',measure);
ta.addEventListener('keydown',function(e){
  if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();post();}
});
send.addEventListener('click',post);
measure();

