js:
var wrap=root.querySelector('.ti2-search-morph-wrap');
var toggle=root.querySelector('.ti2-search-morph-toggle');
var input=root.querySelector('.ti2-search-morph-input');
var clear=root.querySelector('.ti2-search-morph-clear');
var status=root.querySelector('.ti2-search-morph-status');
var LIST=['Deploy to production','Invite teammate','Roll back release','Open changelog','Rotate API key','Pause project','Create environment','Export logs','Assign reviewer'];
function open(state){
  root.classList.toggle('ti2-search-morph-open',state);
  toggle.setAttribute('aria-expanded',state?'true':'false');
  toggle.setAttribute('aria-label',state?'Close command search':'Open command search');
  input.tabIndex=state?0:-1;
  if(state){input.focus();}else{report();}
}
function report(){
  var q=input.value.trim().toLowerCase();
  root.classList.toggle('ti2-search-morph-dirty',q.length>0);
  if(!q){root.classList.remove('ti2-search-morph-empty');status.textContent=LIST.length+' commands available';return;}
  var n=LIST.filter(function(c){return c.toLowerCase().indexOf(q)>-1;}).length;
  root.classList.toggle('ti2-search-morph-empty',n===0);
  status.textContent=n===0?'No commands match that':n+' of '+LIST.length+' commands';
}
toggle.addEventListener('click',function(){
  if(root.classList.contains('ti2-search-morph-open')&&!input.value){open(false);}else{open(true);}
});
input.addEventListener('input',report);
input.addEventListener('blur',function(){if(!input.value)open(false);});
input.addEventListener('keydown',function(e){
  if(e.key!=='Escape')return;
  e.stopPropagation();
  if(input.value){input.value='';report();}else{open(false);toggle.focus();}
});
clear.addEventListener('click',function(){input.value='';report();input.focus();});
report();

