var input=root.querySelector('.ti2-email-verify-input');
var msg=root.querySelector('.ti2-email-verify-msg');
var fix=root.querySelector('.ti2-email-verify-fix');
var sug=root.querySelector('.ti2-email-verify-sug');
var TYPOS={'gmial.com':'gmail.com','gmai.com':'gmail.com','gmail.co':'gmail.com','hotmial.com':'hotmail.com','yaho.com':'yahoo.com','outlok.com':'outlook.com','iclod.com':'icloud.com'};
var RE=/^[^ @]+@[^ @.]+([.][^ @.]+)+$/;
var debounce=0,probe=0,pending='';
function state(s){
  root.classList.toggle('ti2-email-verify-checking',s==='checking');
  root.classList.toggle('ti2-email-verify-valid',s==='valid');
  root.classList.toggle('ti2-email-verify-error',s==='error');
}
function evaluate(){
  var v=input.value.trim();
  fix.hidden=true;
  if(!v){state('');input.removeAttribute('aria-invalid');msg.textContent='We only email about your account.';return;}
  if(!RE.test(v)){state('error');input.setAttribute('aria-invalid','true');msg.textContent='That is not a complete address yet.';return;}
  var domain=v.slice(v.indexOf('@')+1).toLowerCase();
  if(TYPOS[domain]){
    state('error');
    input.setAttribute('aria-invalid','true');
    msg.textContent='Check the domain spelling.';
    pending=v.slice(0,v.indexOf('@'))+'@'+TYPOS[domain];
    sug.textContent='@'+TYPOS[domain];
    fix.hidden=false;
    return;
  }
  state('checking');
  msg.textContent='Checking this address…';
  probe=setTimeout(function(){
    state('valid');
    input.removeAttribute('aria-invalid');
    msg.textContent='Looks good — we can reach you here.';
  },760);
}
input.addEventListener('input',function(){
  clearTimeout(debounce);clearTimeout(probe);
  state('');fix.hidden=true;
  debounce=setTimeout(evaluate,450);
});
input.addEventListener('blur',function(){clearTimeout(debounce);evaluate();});
fix.addEventListener('click',function(){
  input.value=pending;
  clearTimeout(debounce);clearTimeout(probe);
  evaluate();
  input.focus();
});

