var input=root.querySelector('.ti2-mask-phone-input');
var typed=root.querySelector('.ti2-mask-phone-typed');
var rest=root.querySelector('.ti2-mask-phone-rest');
var hint=root.querySelector('.ti2-mask-phone-hint');
var TPL='(___) ___-____';
function digitsOf(s){return (s||'').replace(/[^0-9]/g,'').slice(0,10);}
function fmt(d){
  if(!d.length)return '';
  var o='('+d.slice(0,3);
  if(d.length>3){o+=') '+d.slice(3,6);}else if(d.length===3){o+=') ';}
  if(d.length>6){o+='-'+d.slice(6);}else if(d.length===6){o+='-';}
  return o;
}
function caretFor(s,d,before){
  if(before<=0)return 0;
  if(before>=d.length)return s.length;
  var c=0;
  for(var i=0;i<s.length;i++){
    if(s.charAt(i)>='0'&&s.charAt(i)<='9'){c++;if(c===before)return i+1;}
  }
  return s.length;
}
function paint(){
  var d=digitsOf(input.value);
  var s=fmt(d);
  typed.textContent=s;
  rest.textContent=TPL.slice(s.length);
  var done=d.length===10;
  root.classList.toggle('ti2-mask-phone-done',done);
  input.setAttribute('aria-invalid',(d.length>0&&!done)?'true':'false');
  hint.textContent=done?'Ready — tap continue to get your code':'We text a 6-digit code, never marketing';
}
function reformat(){
  var pos=input.selectionStart||0;
  var before=(input.value.slice(0,pos).replace(/[^0-9]/g,'')).length;
  var d=digitsOf(input.value);
  var s=fmt(d);
  if(input.value!==s)input.value=s;
  var c=caretFor(s,d,before);
  try{input.setSelectionRange(c,c);}catch(e){}
  paint();
}
input.addEventListener('input',reformat);
input.addEventListener('keydown',function(e){
  if(e.key!=='Backspace')return;
  var s=input.selectionStart,t=input.selectionEnd;
  if(s===null||s!==t||s===0)return;
  var prev=input.value.charAt(s-1);
  if(prev>='0'&&prev<='9')return;
  e.preventDefault();
  var i=s;
  while(i>0){
    var ch=input.value.charAt(i-1);
    if(ch>='0'&&ch<='9')break;
    i--;
  }
  if(i>0){
    input.value=input.value.slice(0,i-1)+input.value.slice(s);
    try{input.setSelectionRange(i-1,i-1);}catch(err){}
  }
  reformat();
});
paint();

