function group(s){var o='',c=0;for(var i=s.length-1;i>=0;i--){o=s.charAt(i)+o;c++;if(c%3===0&&i>0)o=','+o;}return o;}
function money(n){var c=Math.round(n*100),w=Math.floor(c/100),f=c-w*100;return group(String(w))+'.'+(f<10?'0'+f:String(f));}
function readValue(){var n=parseFloat(input.value.replace(/[^0-9.]/g,''));return isNaN(n)?0:n;}
function sanitize(raw){
  var v=raw.replace(/[^0-9.]/g,'');
  var dot=v.indexOf('.');
  if(dot>-1)v=v.slice(0,dot+1)+v.slice(dot+1).replace(/[.]/g,'');
  var parts=v.split('.');
  var whole=parts[0].replace(/^0+(?=[0-9])/,'');
  if(whole===''&&parts.length>1)whole='0';
  var out=group(whole);
  if(parts.length>1)out+='.'+parts[1].slice(0,2);
  return out;
}
function check(){
  var over=readValue()>cur().bal+0.0001;
  var was=root.classList.contains('ti2-currency-amount-over');
  root.classList.toggle('ti2-currency-amount-over',over);
  input.setAttribute('aria-invalid',over?'true':'false');
  err.textContent=over?'Over balance':'';
  if(over&&!was){
    root.classList.remove('ti2-currency-amount-shake');
    void root.offsetWidth;
    root.classList.add('ti2-currency-amount-shake');
  }
}
function tweenTo(target){
  cancelAnimationFrame(raf);clearTimeout(guard);
  var from=readValue(),t0=0,dur=420,settled=false;
  function settle(){if(settled)return;settled=true;cancelAnimationFrame(raf);input.value=money(target);check();}
  if(calm){settle();return;}
  function step(now){
    if(settled)return;
    if(!t0)t0=now;
    var p=Math.min(1,(now-t0)/dur);
    var e=1-Math.pow(1-p,3);
    input.value=money(from+(target-from)*e);
    if(p<1){raf=requestAnimationFrame(step);}else{settle();}
  }
  raf=requestAnimationFrame(step);
  guard=setTimeout(settle,dur+160);
}
input.addEventListener('input',function(){
  var caret=input.selectionStart||0;
  var before=input.value.slice(0,caret).replace(/[^0-9.]/g,'').length;
  var out=sanitize(input.value);
  input.value=out;
  var seen=0,place=out.length;
  if(before===0){place=0;}else{
    for(var i=0;i<out.length;i++){
      if(out.charAt(i)!==',')seen++;
      if(seen===before){place=i+1;break;}
    }
  }
  try{input.setSelectionRange(place,place);}catch(e){}
  check();
});
input.addEventListener('blur',function(){
  input.value=money(readValue());
  check();
});
for(var i=0;i<chips.length;i++){
  chips[i].addEventListener('click',function(e){
    var raw=e.currentTarget.getAttribute('data-ti2-add');
    tweenTo(raw==='max'?cur().bal:Math.min(readValue()+parseFloat(raw),999999));
  });
}
pill.addEventListener('click',function(){
  pos=(pos+1)%ORDER.length;
  var c=cur();
  pill.textContent=ORDER[pos];
  pill.setAttribute('aria-label','Currency '+c.name+', activate to change');
  sym.textContent=c.s;
  balnum.textContent=c.s+money(c.bal);
  root.classList.remove('ti2-currency-amount-flip');
  void sym.offsetWidth;
  root.classList.add('ti2-currency-amount-flip');
  check();
});
input.value=money(readValue());
check();
